(()=>{
const panel=document.createElement('details');panel.className='farm-progression';panel.innerHTML='<summary id="growthSummary">🌱 상추부터 시작하는 나의 농장</summary><div id="growthRoad"></div><div id="cowCare"></div>';document.querySelector('.seed-picker').after(panel);
const owner=document.createElement('button');owner.className='farm-owner';owner.onclick=()=>openGameSettings();document.querySelector('.farm-top').prepend(owner);const mode=document.createElement('button');mode.id='playMode';document.querySelector('.compact-topline').prepend(mode);mode.onclick=()=>{if(!window.classroomActive){entrySchool();return}modal('<h2>우리 반 공동 플레이</h2><p>내 농장의 수확과 보관함은 내 기록입니다. 마을에서는 친구들의 작업장을 보고, 장터에서 교환하고, 공동 도시락을 함께 완성해요.</p><button data-close>알겠어요</button>')};
const date=document.querySelector('#compactWeather');date.setAttribute('role','button');date.tabIndex=0;date.onclick=()=>{modal('<h2>마을의 하루는 언제 바뀌나요?</h2><p><b>학급 마을:</b> 선생님이 교사 운영실에서 수업일을 넘겨요. 자정에 자동으로 바뀌지 않아요. 퀴즈·직업 생산·우유는 수업일 기준입니다.</p><p><b>농사:</b> 물을 준 뒤 실제로 20~60초가 지나면 수확할 수 있어요.</p><p><b>공부 기록:</b> 한국 시간의 실제 날짜를 사용해요. 연속 출석은 매일 또는 교사가 지정한 수업일 기준입니다.</p>'+(!window.classroomActive?'<button id="practiceNextDay">혼자 연습 · 다음 날로</button>':'')+'<button data-close>닫기</button>');const b=document.querySelector('#practiceNextDay');if(b)b.onclick=()=>{close();document.querySelector('#nextDay').click()}};date.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();date.click()}};
function draw(){const name=window.classroomActive?(state.name||classroomData.me.accountName):state.name==='나'?'새싹 여행자':state.name||'새싹 여행자';owner.textContent='🌱 '+name+'의 농장 · 내 정보 ›';const heading=document.querySelector('.farm-top h2');if(heading)heading.textContent='내가 가꾸는 텃밭';const ident=window.classroomActive?classroomData.me.id:name;let tint=0;for(const ch of ident)tint=(tint+ch.charCodeAt(0))%4;document.querySelector('#farmScene').style.setProperty('--farm-accent',['#bed397','#abcbd4','#d5becb','#dbc697'][tint]);mode.textContent=window.classroomActive?'👥 학급 '+classroomData.room.code+' · 공동 플레이':'혼자 연습 · 학급 입장';const p=growthBoard?.progress,active=window.classroomActive&&p;const count=active?p.count:0,targets=[0,6,16,30,50];document.querySelectorAll('[data-seed]').forEach(b=>{const i=Number(b.dataset.seed),locked=i>0&&(!active||!p.unlocked[i]);b.disabled=locked;b.title=locked?'누적 수확 '+targets[i]+'개에 열려요':'';b.querySelector('small').textContent=locked?'🔒 누적 수확 '+targets[i]+'개':CROP_TYPES[i].ms/1000+'초 · '+CROP_TYPES[i].yield+'개';if(locked&&selectedCrop===i)selectedCrop=0;b.setAttribute('aria-pressed',String(selectedCrop===i))});const next=targets.find(n=>n>count);document.querySelector('#growthSummary').textContent=active?'🌱 누적 수확 '+count+'개 · '+(next?'다음 씨앗까지 '+(next-count)+'개':count<80?'젖소까지 '+(80-count)+'개':'젖소 돌봄 열림'):'🌱 상추로 연습 · 성장 기록은 학급에서';document.querySelector('#growthRoad').textContent='상추 시작 → 수확 6개 당근 → 16개 토마토 → 30개 감자 → 50개 딸기 → 80개 젖소 (100코인). 기존에 재배하던 작물은 계속 키울 수 있어요.';const c=active?p.cow:null,done=c&&c.milkDay>=state.day;document.querySelector('#cowCare').innerHTML=!active?'<p>학급에 입장하면 씨앗을 차례로 열고 젖소를 돌볼 수 있어요.</p>':!c?'<button data-cow="cow_adopt" '+(count<80||state.coins<100?'disabled':'')+'>🐄 젖소 입양 · 100코인</button>':`<p>🐄 나의 젖소 · ${done?'이번 수업일 우유 수집 완료':c.fedAt?'먹이를 먹고 쉬는 중':'먹이와 물을 기다려요'}</p><button data-cow="cow_feed" ${done||c.fedAt?'disabled':''}>먹이 주기 · 상추 1개</button><button data-cow="cow_water" ${done||c.watered?'disabled':''}>물 주기</button><button data-cow="cow_milk" ${done||!c.fedAt||!c.watered||Date.now()-c.fedAt<20000?'disabled':''}>우유 2개 모으기</button><small>게임 속 돌봄 체험: 먹이와 물을 준 뒤 20초, 수업일마다 한 번.</small>`;}
panel.onclick=async e=>{const b=e.target.closest('[data-cow]');if(!b)return;b.disabled=true;await schoolAction({action:b.dataset.cow});draw()};const oldDraw=drawGrowth;drawGrowth=function(){oldDraw();draw()};const oldRender=render;render=function(){oldRender();draw()};draw();setInterval(()=>{if(!document.hidden)draw()},1000);
})();
